import{z as B,x as p,o as s,c as d,q as l,j as E,D as t,d as r,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"信号量","description":"","frontmatter":{"title":"信号量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/semaphore.md","filePath":"cs/semaphore.md","lastUpdated":1791413859000}'),A={name:"cs/semaphore.md"};function m(c,a,P,V,h,u){const o=p("Mermaid");return s(),d("div",null,[a[2]||(a[2]=l('<h1 id="信号量" tabindex="-1">信号量 <a class="header-anchor" href="#信号量" aria-label="Permalink to &quot;信号量&quot;">​</a></h1><div class="epigraph"><p>P 操作减少信号量并可能睡眠，V 操作增加并可能唤醒；计数把互斥与资源个数写成同一种对象。</p><footer>—— 据 Dijkstra, Cooperating Sequential Processes, 1965 整理</footer></div><p><a href="/cs/seqlock">上一课</a>给出二元互斥。管道满/空、缓冲区槽位、一次性事件，要的是「还剩几个」以及「没有就睡」。缺口不是再发明一种原子指令，而是把锁字推广成<strong>计数</strong>，并把睡眠/唤醒收进原语——信号量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自旋锁在临界区长或条件暂不成立时浪费 CPU。睡眠互斥锁能等「锁被释放」，但不能表达「等三个槽位空出来」。Dijkstra 的信号量 \\(S\\) 是整数：<code>P(S)</code> 原子地等 \\(S\\gt 0\\) 再减一，<code>V(S)</code> 加一并唤醒。互斥是 \\(S\\) 初值为 \\(1\\) 的特例。缺口是这条原语，不是新的调度器。</p><p>本课不把 Linux <code>down_interruptible</code> 的信号可打断语义写完。</p><p><span class="marginnote">数字实例：缓冲区有 3 个空槽，\\(S=3\\)。生产者每放一件做一次 P，\\(S\\) 依次变 \\(2,1,0\\)；第四个生产者做 P 时 \\(S=0\\) 不满足 \\(S\\gt 0\\)，于是睡眠——直到消费者取走一件、做 V 把 \\(S\\) 加回 \\(1\\) 并唤醒它。</span></p><p><span class="marginnote">二元信号量像锁，但习惯上不绑定「持有者」：V 可以由另一进程做，这既是灵活也是后课管程要收紧的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内核实现：<code>P</code> 在关中断或持自旋下检查计数，不够则把线程挂到该信号量的等待队列并切换；<code>V</code> 加计数，若有等待者则唤醒。用户库可经系统调用使用。生产者—消费者：空槽与满槽两个信号量，外加互斥保护头尾指针——互斥仍用上一课的锁或第三个信号量。</p>',10)),(s(),E(n,null,{default:t(()=>[i(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22P%3A%20%E8%AE%A1%E6%95%B0%E4%B8%8D%E8%B6%B3%E5%88%99%E7%9D%A1%E7%9C%A0%22%5D%20--%3E%20Q%5B%22%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20V%5B%22V%3A%20%E5%8A%A0%E8%AE%A1%E6%95%B0%22%5D%20--%3E%20W%5B%22%E5%94%A4%E9%86%92%22%5D%0A%20%20Q%20--%3E%20W%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("信号量把"),e("a",{href:"/cs/scheduling-metrics"},"调度"),r("与同步接起来：睡是阻塞状态，V 把人放回就绪。管道的「满写睡」正是对缓冲剩余空间做 P。与纯锁不同，V 可以在中断下半部调用（若实现允许），从而设备完成直接对应「多了一个满槽」。")],-1)),a[5]||(a[5]=e("p",null,"计数没有类型系统：对错的信号量做 V 会悄悄破坏不变量。这是下一课管程用语言括号把条件等待收进去的动机。",-1)),a[6]||(a[6]=e("p",null,"上面那张图画的是单信号量的 P/V 内部；下面这张回答「两个信号量加一把互斥怎么拼出生产者—消费者」——空槽计数限制生产、满槽计数限制消费，互斥只保护缓冲区本身。",-1)),(s(),E(n,null,{default:t(()=>[i(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E7%A9%BA%E6%A7%BD%E4%BF%A1%E5%8F%B7%E9%87%8F%20S_empty%20%3D%203%22%5D%20--%3E%20PA%5B%22%E7%94%9F%E4%BA%A7%E8%80%85%20P(%E7%A9%BA%E6%A7%BD)%22%5D%0A%20%20PA%20--%3E%20MU%5B%22P(%E4%BA%92%E6%96%A5)%20%E8%BF%9B%E5%85%A5%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20MU%20--%3E%20PB%5B%22%E6%94%BE%E4%B8%80%E4%BB%B6%E4%BA%A7%E5%93%81%22%5D%0A%20%20PB%20--%3E%20VB%5B%22V(%E4%BA%92%E6%96%A5)%20%E9%80%80%E5%87%BA%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20VB%20--%3E%20VF%5B%22V(%E6%BB%A1%E6%A7%BD)%22%5D%0A%20%20VF%20--%3E%20F%5B%22%E6%BB%A1%E6%A7%BD%E4%BF%A1%E5%8F%B7%E9%87%8F%20S_full%22%5D%0A%20%20F%20--%3E%20PC%5B%22%E6%B6%88%E8%B4%B9%E8%80%85%20P(%E6%BB%A1%E6%A7%BD)%20%E5%90%8E%E5%8F%96%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">术语翻译：等待队列就是内核给每个信号量挂的一张「睡着等这个计数的人」名单——P 发现计数不够就把线程登记上去并切走，V 做完加法后按名单叫醒一个人。所以「等三个空槽」和「等一把锁」走的是同一套机制。</span></p><p><span class="marginnote">常见误区：初学者容易以为信号量必须「谁 P 的谁 V」。实际上 V 不检查调用者——任何人甚至中断处理程序都能对它做 V，这正是它能表达「资源多了一个」的原因，也是 V 写错对象时错误悄悄扩散、难排查的根源。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把管程当信号量的宏展开讲完，不引入 barrier、rwlock 的全部变体。也不把 System V 信号量数组的 API 背下来。死锁可以在多信号量上发生，条件在再后一课。</p><p>P 在被信号打断后是否重做，属于接口；课内默认 P 会完成或明确失败，不把 EINTR 表背完。</p><p>忙等信号量极少见，计数等待的意义就是去睡眠。</p><p>后课默认：可以用 P/V 等待资源个数。希望「锁与条件在同一模块里由编译器看管」，下一课管程与条件变量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>信号量是带睡眠的计数；互斥是初值为一的特例。</li><li>P/V 把阻塞与唤醒做成原语，对接调度。</li><li>误用 V 难以检查，推动管程。</li><li>出处：Dijkstra, <em>Cooperating Sequential Processes</em>, 1965；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const f=B(A,[["render",m]]);export{S as __pageData,f as default};
